library DeltaLib {
    uint256 internal constant BPS_DENOMINATOR = 10000;
    uint256 internal constant PRECISION = 1e18;

struct ChainCredit {
    uint256 credit;         // Current credit allocation
    uint256 utilized;       // Credit currently in use
    uint256 lastUpdate;     // Last update timestamp
}

function _buildDepositPayload(uint256 assets, address receiver) internal pure returns (bytes memory) {
    return abi.encodePacked(MSG_DEPOSIT, abi.encode(receiver, assets));
}

function _handleDeploy(bytes calldata _payload) internal {
    (, uint256 amount, address protocol, string memory protocolName) =
        abi.decode(_payload, (bytes1, uint256, address, string));

    address implementation = protocolImplementations[protocolName];
    if (implementation == address(0)) revert ProtocolNotSupported();

    // Transfer assets to protocol (simplified - actual implementation would call protocol)
    protocolDeposits[protocol] += amount;
    totalDeposited += amount;

    emit Deployed(protocol, protocolName, amount);
}

function removeLiquidity(uint256 amount) external override nonReentrant whenNotPaused {
    if (amount == 0) revert InvalidAmount();

    uint256 poolBalance = _asset.balanceOf(address(this));
    if (amount > poolBalance) revert InsufficientLiquidity();

    _asset.safeTransfer(msg.sender, amount);

    emit LiquidityRemoved(msg.sender, amount);
}
